// Original synthesized audio; enabled only after a player gesture.
export class DriveAudio{
 constructor(){this.ctx=null;this.enabled=true;this.lastImpact=0;}
 unlock(){if(!this.ctx){const C=window.AudioContext||window.webkitAudioContext;if(!C)return;this.ctx=new C();this.gain=this.ctx.createGain();this.gain.gain.value=0;this.gain.connect(this.ctx.destination);this.engine=this.ctx.createOscillator();this.engine.type='sawtooth';this.filter=this.ctx.createBiquadFilter();this.filter.type='lowpass';this.filter.frequency.value=300;this.engine.connect(this.filter);this.filter.connect(this.gain);this.engine.start();const buffer=this.ctx.createBuffer(1,this.ctx.sampleRate,this.ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;this.noise=this.ctx.createBufferSource();this.noise.buffer=buffer;this.noise.loop=true;this.noiseFilter=this.ctx.createBiquadFilter();this.noiseFilter.type='bandpass';this.noiseFilter.frequency.value=1800;this.noiseGain=this.ctx.createGain();this.noiseGain.gain.value=0;this.noise.connect(this.noiseFilter);this.noiseFilter.connect(this.noiseGain);this.noiseGain.connect(this.ctx.destination);this.noise.start();}this.ctx.resume().catch(()=>{});}
 update(state,controls,paused,enabled=true){if(!this.ctx)return;const t=this.ctx.currentTime,active=!paused&&enabled;this.engine.frequency.setTargetAtTime(25+state.rpm/65,t,.04);this.filter.frequency.setTargetAtTime(180+state.rpm*.12,t,.08);this.gain.gain.setTargetAtTime(active?(controls.throttle?.035:.018):0,t,.05);this.noiseGain.gain.setTargetAtTime(active?((controls.drifting||controls.burnout)?.035:0)+state.impact*.08:0,t,.04);}
}
